# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

# Two connections race the adapter's locks. The first writer runs inside an
# outer transaction paused on a queue, so the adapter's savepoint keeps every
# lock it took until the example releases it. Each example proves the second
# writer waits on that writer with blocked_by?, checks the second writer has
# committed nothing while it waits, then releases and checks the answers and
# the committed rows.
#
# The adapter is called directly: the invoice coordinator's per-invoice
# advisory lock would serialize the writers before they reach these locks.
RSpec.describe Invoices::PreparedReservations, "with competing writers", committed_data: true do
  include PreparedReservationsSpecSupport

  # The committed-data reset leaves ownership with the legacy store.
  before { prepare_local_ownership! }

  let(:company) { create(:company) }
  let(:adapter) { described_class.new }
  let(:reached) { Queue.new }
  let(:release) { Queue.new }
  let(:holder_pids) { Queue.new }
  let(:waiter_pids) { Queue.new }

  # Runs the block on its own connection inside a transaction that pauses
  # once the block returns, and answers the block's outcome after the
  # transaction commits, or rolls back when roll_back is set.
  def hold_writer(roll_back: false)
    committed_data_thread(holder_pids) do
      held = nil
      ApplicationRecord.transaction do
        held = yield
        reached << true
        release.pop
        raise ActiveRecord::Rollback if roll_back
      end
      held
    end
  end

  def start_waiter(&block)
    expect(reached.pop(timeout: 5)).to be(true), "the first writer never reached its pause"
    committed_data_thread(waiter_pids, &block)
  end

  # True when the waiter is blocked by the paused writer. Reads the block's
  # result from the test's own connection while both are still running, and
  # releases the paused writer whatever happens, so a failed check cannot
  # leave it holding locks.
  def blocked_while_held
    blocked = blocked_by?(waiter_pids.pop(timeout: 5), holder_pids.pop(timeout: 5))
    [blocked, (yield if block_given?)]
  ensure
    release << true
  end

  after do
    release.push(true)
    [@holder, @waiter].compact.each { |thread| thread.join(5) }
  end

  # Shared lock: the entry row FOR UPDATE in lock_entries. The abort takes it
  # before it writes any snapshot, and the waiting prepare reaches it before
  # it reads the reserved flag. A prepare that read the flag before the wait
  # would still see the entry reserved, find no flip, and skip its version
  # bump and snapshot. Without the entry lock it would see the first invoice's
  # provisional row and answer refused.
  it "a prepare waiting behind an abort re-reads the entry as free and bumps its version and snapshot exactly once" do
    entry = prepared_spec_entry(company)
    first_invoice = prepared_spec_invoice(company)
    second_invoice = prepared_spec_invoice(company)
    first_request = prepared_spec_request(company, first_invoice, [entry.id])
    second_request = prepared_spec_request(company, second_invoice, [entry.id])
    expect(adapter.prepare(first_request).state).to eq("prepared")
    version_before = entry.reload.version
    outbox_before = prepared_spec_outbox_count(entry)

    @holder = hold_writer { adapter.abort(first_request) }
    @waiter = start_waiter { adapter.prepare(second_request) }
    blocked, operations_while_held = blocked_while_held { prepared_spec_operations(company, second_invoice) }

    expect(blocked).to be(true), "the prepare never waited on the abort's entry lock"
    expect(operations_while_held).to eq([])
    held = @holder.join(5)&.value
    expect([held&.state, held&.counts]).to eq(["aborted", { dropped: 1 }])
    expect(@waiter.join(5)&.value&.state).to eq("prepared")
    expect(prepared_spec_operations(company, first_invoice).map(&:first)).to eq(["aborted"])
    expect(prepared_spec_operations(company, second_invoice).map(&:first)).to eq(["prepared"])
    expect(prepared_spec_reservations(company)).to eq([[entry.id, second_invoice.id, "provisional", "active"]])
    # One bump and snapshot for the abort freeing the entry, one for the
    # prepare reserving it again.
    expect(entry.reload.version).to eq(version_before + 2)
    expect(prepared_spec_outbox_count(entry)).to eq(outbox_before + 2)
  end

  # Shared lock: the entry row FOR UPDATE in lock_entries. The waiter's answer
  # depends on the provisional row it reads after the wait; without the lock
  # it would reach the one-provisional-per-entry index and answer retryable.
  it "a prepare of the same entry for another invoice waits on the entry lock and is refused as provisional_elsewhere" do
    entry = prepared_spec_entry(company)
    first_invoice = prepared_spec_invoice(company)
    second_invoice = prepared_spec_invoice(company)
    first_request = prepared_spec_request(company, first_invoice, [entry.id])
    second_request = prepared_spec_request(company, second_invoice, [entry.id])
    version_before = entry.reload.version
    outbox_before = prepared_spec_outbox_count(entry)

    @holder = hold_writer { adapter.prepare(first_request) }
    @waiter = start_waiter { adapter.prepare(second_request) }
    blocked, reservations_while_held = blocked_while_held { prepared_spec_reservations(company) }

    expect(blocked).to be(true), "the second prepare never waited on the entry lock"
    expect(reservations_while_held).to eq([])
    expect(@holder.join(5)&.value&.state).to eq("prepared")
    lost = @waiter.join(5)&.value
    expect(lost&.state).to eq("refused")
    expect(lost&.conflicts).to eq([{ entry_id: entry.id, reason: "provisional_elsewhere" }])
    expect(prepared_spec_operations(company, first_invoice).map(&:first)).to eq(["prepared"])
    expect(prepared_spec_operations(company, second_invoice)).to eq([])
    expect(prepared_spec_reservations(company)).to eq([[entry.id, first_invoice.id, "provisional", "active"]])
    expect(entry.reload.version).to eq(version_before + 1)
    expect(prepared_spec_outbox_count(entry)).to eq(outbox_before + 1)
  end

  # Shared lock: index_invoice_operations_one_prepared_per_invoice. The two
  # prepares name different entries, so they share no entry lock. The second
  # cannot see the uncommitted operation in its unresolved check, so it waits
  # at the operation insert, before it writes any snapshot, and recovers from
  # the unique violation once the first commits.
  it "a prepare of the same invoice on another entry waits on the one-prepared index and answers unresolved_operation with no writes" do
    first_entry = prepared_spec_entry(company)
    second_entry = prepared_spec_entry(company)
    invoice = prepared_spec_invoice(company)
    first_request = prepared_spec_request(company, invoice, [first_entry.id])
    second_request = prepared_spec_request(company, invoice, [second_entry.id])
    first_version_before = first_entry.reload.version
    second_version_before = second_entry.reload.version
    first_outbox_before = prepared_spec_outbox_count(first_entry)
    second_outbox_before = prepared_spec_outbox_count(second_entry)

    @holder = hold_writer { adapter.prepare(first_request) }
    @waiter = start_waiter { adapter.prepare(second_request) }
    blocked, operations_while_held = blocked_while_held { prepared_spec_operations(company, invoice) }

    expect(blocked).to be(true), "the second prepare never waited on the one-prepared-per-invoice index"
    expect(operations_while_held).to eq([])
    expect(@holder.join(5)&.value&.state).to eq("prepared")
    lost = @waiter.join(5)&.value
    expect([lost&.state, lost&.reason]).to eq(["retryable", "unresolved_operation"])
    expect(prepared_spec_operations(company, invoice).map(&:first)).to eq(["prepared"])
    expect(prepared_spec_reservations(company)).to eq([[first_entry.id, invoice.id, "provisional", "active"]])
    expect(first_entry.reload.version).to eq(first_version_before + 1)
    expect(prepared_spec_outbox_count(first_entry)).to eq(first_outbox_before + 1)
    expect(second_entry.reload.version).to eq(second_version_before)
    expect(prepared_spec_outbox_count(second_entry)).to eq(second_outbox_before)
  end

  # Shared lock: the invoice_operations row lock in finish. The abort takes it
  # as its first statement, before any entry lock or snapshot. Without it the
  # abort would read the operation as prepared and overwrite the commit's
  # settled state. The losing finish answers its own settled state with empty
  # counts.
  it "an abort waiting behind a commit of the same operation leaves it committed and changes nothing" do
    entry = prepared_spec_entry(company)
    invoice = prepared_spec_invoice(company)
    request = prepared_spec_request(company, invoice, [entry.id])
    expect(adapter.prepare(request).state).to eq("prepared")
    version_before = entry.reload.version
    outbox_before = prepared_spec_outbox_count(entry)

    @holder = hold_writer { adapter.commit(request) }
    @waiter = start_waiter { adapter.abort(request) }
    blocked, operations_while_held = blocked_while_held { prepared_spec_operations(company, invoice).map(&:first) }

    expect(blocked).to be(true), "the abort never waited on the operation row lock"
    expect(operations_while_held).to eq(["prepared"])
    won = @holder.join(5)&.value
    expect([won&.state, won&.counts]).to eq(["committed", { reserved: 1, released: 0 }])
    lost = @waiter.join(5)&.value
    expect([lost&.state, lost&.counts]).to eq(["aborted", {}])
    expect(prepared_spec_operations(company, invoice).map(&:first)).to eq(["committed"])
    expect(prepared_spec_reservations(company)).to eq([[entry.id, invoice.id, "committed", "active"]])
    # Provisional to committed keeps the entry reserved, so neither finish
    # bumps the version or writes a snapshot.
    expect(entry.reload.version).to eq(version_before)
    expect(prepared_spec_outbox_count(entry)).to eq(outbox_before)
  end

  # Shared lock: the invoice_operations row lock in finish. The commit takes
  # it as its first statement, before the entry lock and the outbox lock the
  # abort also holds.
  it "a commit waiting behind an abort of the same operation leaves it aborted and adds no version or snapshot" do
    entry = prepared_spec_entry(company)
    invoice = prepared_spec_invoice(company)
    request = prepared_spec_request(company, invoice, [entry.id])
    expect(adapter.prepare(request).state).to eq("prepared")
    version_before = entry.reload.version
    outbox_before = prepared_spec_outbox_count(entry)

    @holder = hold_writer { adapter.abort(request) }
    @waiter = start_waiter { adapter.commit(request) }
    blocked, reservations_while_held = blocked_while_held { prepared_spec_reservations(company) }

    expect(blocked).to be(true), "the commit never waited on the operation row lock"
    expect(reservations_while_held).to eq([[entry.id, invoice.id, "provisional", "active"]])
    won = @holder.join(5)&.value
    expect([won&.state, won&.counts]).to eq(["aborted", { dropped: 1 }])
    lost = @waiter.join(5)&.value
    expect([lost&.state, lost&.counts]).to eq(["committed", {}])
    expect(prepared_spec_operations(company, invoice).map(&:first)).to eq(["aborted"])
    expect(prepared_spec_reservations(company)).to eq([])
    # The abort frees the entry: one bump and one snapshot, none from the commit.
    expect(entry.reload.version).to eq(version_before + 1)
    expect(prepared_spec_outbox_count(entry)).to eq(outbox_before + 1)
  end

  # Rollback control: it shows the waiter wins once the first writer rolls
  # back. It does not prove the entry lock on its own, because without that
  # lock the waiter would block on the one-provisional-per-entry index and
  # still succeed.
  it "a prepare waiting behind a rolled-back prepare of the same entry wins with exactly one version bump and snapshot" do
    entry = prepared_spec_entry(company)
    first_invoice = prepared_spec_invoice(company)
    second_invoice = prepared_spec_invoice(company)
    first_request = prepared_spec_request(company, first_invoice, [entry.id])
    second_request = prepared_spec_request(company, second_invoice, [entry.id])
    version_before = entry.reload.version
    outbox_before = prepared_spec_outbox_count(entry)

    @holder = hold_writer(roll_back: true) { adapter.prepare(first_request) }
    @waiter = start_waiter { adapter.prepare(second_request) }
    blocked, = blocked_while_held

    expect(blocked).to be(true), "the second prepare never waited on the first prepare"
    expect(@holder.join(5)&.value&.state).to eq("prepared")
    expect(@waiter.join(5)&.value&.state).to eq("prepared")
    expect(prepared_spec_operations(company, first_invoice)).to eq([])
    expect(prepared_spec_operations(company, second_invoice).map(&:first)).to eq(["prepared"])
    expect(prepared_spec_reservations(company)).to eq([[entry.id, second_invoice.id, "provisional", "active"]])
    expect(entry.reload.version).to eq(version_before + 1)
    expect(prepared_spec_outbox_count(entry)).to eq(outbox_before + 1)
  end
